/* Glossary. Terms are auto-detected in lesson bodies and answer explanations,
   underlined, and given a hover/tap tooltip with a definition and a link to the
   lesson that covers them.

   Format:  "term": { d: "definition", l: "lesson-id", aka: ["alias", ...] }

   Keep terms UNAMBIGUOUS. A word that has an ordinary English meaning in this
   material (clean, section, tick, fake, spy) will false-positive constantly, so
   either use the longer phrase or leave it out. */

const GLOSSARY = {

// ---- concurrency and interrupts -------------------------------------------
"atomic": { d: "Indivisible: it either happens completely or not at all, with no point in the middle where another context can see a half-finished state. <code>reg |= bit</code> is NOT atomic, because it is a load, an OR and a store.", l: "emb-concurrency", aka: ["atomicity", "atomically"] },
"memory barrier": { d: "An instruction telling the CPU not to move memory accesses across this point. Needed on cores with write buffers or out-of-order execution. <code>volatile</code> is a compiler instruction and is not a barrier.", l: "emb-dma", aka: ["memory barriers", "barrier instruction"] },
"reentrant": { d: "Safe to call again while a previous call is still part-way through, typically because an interrupt preempted it. Requires no shared static or global state.", l: "emb-isr", aka: ["reentrancy", "non-reentrant"] },
"race condition": { d: "A bug whose outcome depends on the relative timing of two contexts. Usually caused by two things touching the same data with nothing enforcing an order.", l: "emb-concurrency", aka: ["race conditions"] },
"critical section": { d: "A span of code during which interrupts (or the scheduler) are disabled so a sequence completes without interference. Keep them as short as possible: they add to every interrupt's latency.", l: "emb-concurrency", aka: ["critical sections"] },
"priority inversion": { d: "A high-priority task is blocked on a mutex held by a low-priority task, which cannot run because a medium-priority task keeps preempting it. Caused the Mars Pathfinder resets.", l: "emb-rtos" },
"priority inheritance": { d: "The kernel temporarily raises a mutex holder's priority to that of the highest task waiting on it, so it finishes and releases. This is what prevents priority inversion, and it is why a mutex is not a semaphore.", l: "emb-rtos" },
"mutex": { d: "A lock with an <b>owner</b>, used for mutual exclusion. Because the kernel knows who holds it, it can apply priority inheritance.", l: "emb-rtos", aka: ["mutexes"] },
"semaphore": { d: "A counter with no owner, used for signalling. Anyone can give it. Because there is no owner, it cannot provide priority inheritance.", l: "emb-rtos", aka: ["semaphores"] },
"deadlock": { d: "Two or more contexts each waiting for something only the other can release, so none of them ever proceeds.", l: "emb-rtos" },
"starvation": { d: "A task never gets to run because something of higher priority never blocks. On a strictly priority-based scheduler this is guaranteed, not merely likely.", l: "emb-rtos" },
"ISR": { d: "Interrupt Service Routine: the function the hardware calls when an interrupt fires. It must not block, must not allocate, and should be as short as possible.", l: "emb-isr", aka: ["ISRs", "interrupt handler", "interrupt handlers", "interrupt context"] },
"interrupt latency": { d: "The time between an interrupt asserting and its handler starting. A global property: anything that disables interrupts, or any long handler, spends everyone's budget.", l: "emb-realtime" },
"jitter": { d: "Variation in timing between one occurrence and the next. Often matters more than absolute latency, because control algorithms assume a fixed timestep.", l: "emb-realtime" },
"WCET": { d: "Worst-Case Execution Time. The number a deadline is missed by, so it must be measured under worst-case conditions: cold cache, every branch taken, flash busy, all interrupts enabled.", l: "emb-realtime", aka: ["worst-case execution time"] },
"preempt": { d: "To interrupt a running task and switch to a more urgent one before the first has finished.", l: "emb-rtos", aka: ["preempts", "preempted", "preemption", "preemptive"] },
"context switch": { d: "Saving one task's registers and stack pointer and restoring another's, so the CPU resumes a different task.", l: "emb-rtos", aka: ["context switches"] },
"ring buffer": { d: "A fixed array with a head and a tail index used as a queue. With one producer and one consumer, and one slot sacrificed, it needs no lock at all.", l: "emb-concurrency", aka: ["ring buffers", "circular buffer"] },
"FromISR": { d: "The RTOS API variant safe to call from interrupt context: it never blocks, and it reports whether a higher-priority task was woken so the handler can yield.", l: "emb-rtos" },
"bus master": { d: "Anything that can initiate transfers on the memory bus. The CPU is one; a DMA controller is another, which is why masking interrupts does not stop DMA.", l: "emb-dma", aka: ["bus masters"] },

// ---- C language traps -----------------------------------------------------
"integer promotion": { d: "Any type narrower than <code>int</code> is converted to <code>int</code> before an operator is applied. This is why <code>~a</code> on a <code>uint8_t</code> gives 0xFFFFFF00, not 0x00.", l: "emb-types", aka: ["integer promotions", "promoted", "promotes", "promotion"] },
"undefined behaviour": { d: "The standard imposes no requirements at all, so the optimiser may assume it never happens and delete code that would only run if it did. Not 'unpredictable': actively exploited.", l: "emb-ub", aka: ["undefined behavior", "UB"] },
"implementation-defined": { d: "The behaviour is chosen by the compiler and must be documented. Legal but not portable. The signedness of plain <code>char</code> is the classic example.", l: "emb-types" },
"strict aliasing": { d: "The compiler may assume that objects of different types do not share memory. Casting a <code>uint8_t*</code> to an <code>int16_t*</code> breaks that assumption and produces bugs that only appear at -O2.", l: "emb-ub" },
"sequence point": { d: "A point in execution where all previous side effects have completed. Modifying the same object twice without one between, as in <code>i = i++</code>, is undefined.", l: "emb-ub", aka: ["sequence points"] },
"sign extension": { d: "When a narrow signed value widens, the sign bit is copied into the new high bits. A <code>signed char</code> holding 0x80 becomes 0xFFFFFF80, not 0x00000080.", l: "emb-types", aka: ["sign-extend", "sign-extends", "sign extend"] },
"two's complement": { d: "The standard binary representation for signed integers, where the top bit carries negative weight. Since C23 it is the only representation the standard allows.", l: "emb-types" },
"padding": { d: "Bytes the compiler inserts between struct members so each one lands on an address its type requires. Their contents are unspecified, which is why you must never send a struct down a wire.", l: "emb-structs", aka: ["pad bytes", "padding bytes", "tail padding"] },
"alignment": { d: "The requirement that an object's address be a multiple of some value, usually its size. A 32-bit load normally needs a 4-byte-aligned address.", l: "emb-structs", aka: ["aligned", "unaligned", "unaligned access"] },
"endianness": { d: "The order in which the bytes of a multi-byte value are stored. Little-endian puts the least significant byte at the lowest address; ARM and x86 are little-endian, network protocols are traditionally big-endian.", l: "emb-serial", aka: ["little-endian", "big-endian", "byte order"] },
"decay": { d: "An array used in an expression becomes a pointer to its first element. It is why an array parameter loses its size, and why <code>sizeof(buf)</code> inside a function gives the pointer size.", l: "emb-pointers", aka: ["decays", "decayed"] },
"dangling pointer": { d: "A pointer to memory whose lifetime has ended, such as a returned local. It frequently appears to work, because nothing erases the bytes until something reuses them.", l: "emb-pointers", aka: ["dangling"] },
"type punning": { d: "Reading the same bytes as a different type. Safe via <code>memcpy</code> or (in C) a union; unsafe via a pointer cast, which breaks strict aliasing.", l: "emb-ub" },
"translation unit": { d: "One .c file plus everything it includes, as seen by the compiler. A <code>static</code> variable in a header gives every translation unit its own private copy.", l: "emb-preproc", aka: ["translation units"] },
"internal linkage": { d: "A symbol visible only within its own translation unit, which is what <code>static</code> at file scope gives you. It also suppresses the duplicate-symbol link error.", l: "emb-preproc" },
"opaque handle": { d: "A struct declared in a header but defined only in the .c file. Callers can hold a pointer and nothing else, so internals change without recompiling users.", l: "emb-drivers", aka: ["opaque type", "opaque struct"] },
"static assert": { d: "A condition checked by the compiler. Generates no code, cannot be disabled by NDEBUG, and a failing one never ships because the build does not exist.", l: "emb-errors", aka: ["_Static_assert", "static_assert"] },

// ---- memory and build -----------------------------------------------------
".bss": { d: "The section holding uninitialised (or zero-initialised) globals and statics. Costs RAM only: startup simply zeroes the region, so nothing needs storing in flash.", l: "emb-memory" },
".data": { d: "The section holding globals and statics with a non-zero initialiser. Costs flash <b>and</b> RAM: the values live in flash and startup copies them into RAM.", l: "emb-memory" },
".rodata": { d: "Read-only data: <code>const</code> tables and string literals. Lives in flash only, which is why adding <code>const</code> to a large table halves what it costs you.", l: "emb-memory" },
".text": { d: "The section holding executable code. Lives in flash and is normally executed in place.", l: "emb-memory" },
"linker script": { d: "The file declaring the physical memory regions and mapping output sections into them. The only place that can control where things live.", l: "emb-build", aka: ["linker scripts"] },
"map file": { d: "The linker's report of every symbol, its size and which object file it came from. The tool that answers 'why did my firmware grow 40 kB'.", l: "emb-build" },
"LMA": { d: "Load Memory Address: where a section is stored in the image, typically flash. For <code>.data</code> this differs from where it runs.", l: "emb-build", aka: ["load address"] },
"VMA": { d: "Virtual Memory Address: where a section actually lives when the program runs. For <code>.data</code> this is RAM.", l: "emb-build", aka: ["run address"] },
"startup code": { d: "The code that runs before <code>main</code>: it copies .data from flash to RAM, zeroes .bss, runs static constructors, then calls main.", l: "emb-memory", aka: ["Reset_Handler"] },
"vector table": { d: "The table of exception handler addresses. On Cortex-M the first word is the initial stack pointer and the second is the reset vector, both read by hardware before any code runs.", l: "emb-memory" },
"stack frame": { d: "The region of stack belonging to one function call, holding its locals and saved registers. Released on return, though nothing erases it.", l: "emb-memory", aka: ["stack frames"] },
"high water mark": { d: "The minimum free stack a task has ever had. FreeRTOS fills the stack with a pattern and counts what remains untouched, which is how you size a stack by measurement rather than guess.", l: "emb-rtos" },
"ELF": { d: "The linker's full output: code, data, symbols and debug information. Flash the stripped .bin, but archive the ELF, because fault addresses from the field only decode against it.", l: "emb-build" },
"objcopy": { d: "The tool that extracts the raw bytes from an ELF into a .bin or .hex for flashing, discarding the symbols and debug information.", l: "emb-build" },

// ---- faults and debugging -------------------------------------------------
"watchdog": { d: "An independent timer that resets the part if software stops proving it is alive. Any change making it less likely to fire is making it worse at its only job.", l: "emb-faults", aka: ["watchdogs"] },
"brownout": { d: "The supply voltage sagging below the part's minimum. Produces faults that look exactly like software bugs, which is why you measure the rails first.", l: "emb-diagnose" },
"hard fault": { d: "The Cortex-M catch-all exception. Common causes: null dereference, unaligned access on M0, and touching a peripheral whose clock is off.", l: "emb-faults", aka: ["hard faults", "bus fault", "usage fault", "memory management fault"] },
"CFSR": { d: "Configurable Fault Status Register: the Cortex-M register whose bits say which category of fault occurred. Read it in your fault handler rather than guessing.", l: "emb-faults" },
"EXC_RETURN": { d: "The magic value the core puts in LR on exception entry. Not an address: the top bits are all ones and the low bits encode which mode and stack to return to. Bit 2 tells a fault handler which stack holds the frame.", l: "emb-cm-exceptions" },
"tail-chaining": { d: "When an exception is pending as a handler returns, the core skips unstacking and immediately restacking the same eight registers and goes straight into the next handler. Roughly six cycles instead of about twenty-four.", l: "emb-cm-exceptions", aka: ["tail chaining"] },
"lazy stacking": { d: "The core reserves stack space for the FPU registers on exception entry but only fills it if the handler actually uses a float. Makes the frame 104 bytes rather than 32 when FPU context is active.", l: "emb-cm-exceptions", aka: ["lazy FPU stacking"] },
"stacked frame": { d: "The eight registers the core pushes automatically on exception entry: R0 to R3, R12, LR, PC, xPSR, with R0 lowest. The stacked PC at offset 0x18 is the faulting instruction.", l: "emb-cm-exceptions", aka: ["exception stack frame", "stack frame on entry"] },
"PRIMASK": { d: "A single bit that blocks every configurable-priority interrupt. What <code>__disable_irq()</code> sets. NMI and HardFault still get through.", l: "emb-cm-nvic" },
"BASEPRI": { d: "Masks only interrupts whose priority number is greater than or equal to the value written, so urgent ones keep running. Zero disables the masking. This is what lets an RTOS protect its data while leaving high priority interrupts with bounded latency.", l: "emb-cm-nvic" },
"FAULTMASK": { d: "Like PRIMASK but also blocks HardFault. Almost never what you want, since it turns a diagnosable fault into a lockup.", l: "emb-cm-nvic" },
"PendSV": { d: "An exception with no hardware source: software sets its pending bit and it runs when nothing more urgent is left. Set to the lowest priority so an RTOS context switch cannot run while another handler is still in progress.", l: "emb-cm-systick" },
"SysTick": { d: "A 24-bit down counter inside the core rather than the vendor peripheral block, so it is at the same address on every Cortex-M. The usual RTOS tick source. It stops in most sleep modes, which is why tickless idle needs a separate timer.", l: "emb-cm-systick" },
"SVC": { d: "A synchronous exception raised by the <code>svc</code> instruction, the Cortex-M equivalent of a system call. How unprivileged code asks the kernel to do something privileged.", l: "emb-cm-systick", aka: ["supervisor call"] },
"VTOR": { d: "Vector Table Offset Register: where the core looks for exception handlers. A bootloader must set it before jumping to the application, or every interrupt dispatches into the bootloader's handlers.", l: "emb-cm-memory" },
"DMB": { d: "Data Memory Barrier. Memory accesses before it are observed before those after it. It orders, but does not wait for completion.", l: "emb-cm-memory" },
"DSB": { d: "Data Synchronisation Barrier. Stronger than DMB: execution stops until every preceding memory access has actually completed.", l: "emb-cm-memory" },
"ISB": { d: "Instruction Synchronisation Barrier. Flushes the pipeline so instructions after it are fetched afresh. Needed after any context-changing write, and always paired as DSB then ISB.", l: "emb-cm-memory" },
"bit-banding": { d: "On Cortex-M3 and M4 only, an alias region where each word maps to one bit of SRAM or peripheral space, so a bit can be set with a single atomic store. Absent on M0, M0+ and M7, which makes it a portability trap.", l: "emb-cm-memory", aka: ["bit band"] },
"Thumb": { d: "The only instruction set Cortex-M executes. Because there is no other state to switch to, bit 0 of every branch target must be 1, which is why function pointers hold odd addresses.", l: "emb-cm-model", aka: ["Thumb-2"] },
"MSP": { d: "Main Stack Pointer. Handler mode always uses it. Bare metal firmware often uses it for everything; an RTOS keeps it for handlers so a task stack overflow does not take out interrupt handling.", l: "emb-cm-model" },
"PSP": { d: "Process Stack Pointer. The second banked stack pointer, selectable for thread mode via CONTROL, which an RTOS gives to each task.", l: "emb-cm-model" },
"CMSIS": { d: "ARM's core headers and intrinsics, defining SCB, NVIC, SysTick and the rest at their architectural addresses so the same code works across vendors. Mostly headers, not a framework.", l: "emb-cm-cmsis" },
"intrinsic": { d: "A function-shaped wrapper around an instruction C has no syntax for, such as <code>__DSB()</code>, <code>__WFI()</code> or <code>__CLZ()</code>. Compiles to the single instruction with no call overhead.", l: "emb-cm-cmsis", aka: ["intrinsics"] },
"addr2line": { d: "The tool that turns a fault address into a file and line, using the debug information in the ELF. It must be the ELF from that exact build, or it confidently names the wrong function.", l: "emb-cm-cmsis" },
"reset reason": { d: "A register recording why the part last reset: power-on, brownout, watchdog, software or fault. One read distinguishes investigations that would otherwise take hours.", l: "emb-diagnose", aka: ["reset reason register"] },
"NVIC": { d: "Nested Vectored Interrupt Controller: the Cortex-M block that prioritises and dispatches interrupts. Note that a <b>lower</b> priority number means more urgent.", l: "emb-isr" },
"MPU": { d: "Memory Protection Unit: hardware that enforces access permissions on address regions. Can turn a silent stack overflow into an immediate fault.", l: "emb-faults" },
"SWD": { d: "Serial Wire Debug: ARM's two-pin debug interface, a clock and a bidirectional data line. Replaces the wider JTAG when pins are scarce.", l: "emb-debugarch" },
"ITM": { d: "Instrumentation Trace Macrocell: writing a byte to a stimulus port costs a few cycles, so it does not move the timing you are investigating. Unlike printf, which does.", l: "emb-debugarch" },
"ETM": { d: "Embedded Trace Macrocell: records the actual instruction stream, so you can reconstruct what executed before a crash. ITM is instrumentation you insert; ETM records execution itself.", l: "emb-debugarch" },
"DWT": { d: "Data Watchpoint and Trace unit. Its free-running cycle counter is the cheapest accurate way to time a function, with no external tooling.", l: "emb-debugarch" },
"watchpoint": { d: "A breakpoint on <b>data</b>: the core halts when a given address is read or written. The right tool for finding what corrupts a variable.", l: "emb-debugarch", aka: ["watchpoints", "data watchpoint"] },
"logic analyser": { d: "An instrument that captures digital lines and decodes bus protocols. Its most useful output is often a clean trace, which rules out the bus and points at software.", l: "emb-diagnose", aka: ["logic analyzer"] },

// ---- buses and wire protocols ---------------------------------------------
"open-drain": { d: "A pin that can only pull the line low; a pull-up resistor returns it high. Used by I2C so any device can hold the line, but it makes rise time an RC problem.", l: "emb-buses", aka: ["open drain"] },
"pull-up": { d: "A resistor holding a line high when nothing is driving it low. 'Stronger' means <b>lower</b> resistance, which charges the bus capacitance faster.", l: "emb-buses", aka: ["pull-ups", "pullup", "pullups"] },
"rise time": { d: "How long a released line takes to reach a valid high, set by the pull-up resistance times the bus capacitance. Standard-mode I2C allows 1000 ns, fast mode 300 ns.", l: "emb-buses" },
"START condition": { d: "On I2C, SDA falling while SCL is high. During data SDA may only change while SCL is low, so this pattern is unambiguously a control signal.", l: "emb-buses" },
"repeated START": { d: "A second START issued without an intervening STOP, so the bus is never released. This is what makes a register read one indivisible transaction.", l: "emb-buses" },
"NAK": { d: "No acknowledge: nobody pulled SDA low on the ninth clock. On the address byte it means nothing at that address responded, so there is no data to have been corrupted.", l: "emb-buses", aka: ["NACK", "ACK"] },
"clock stretching": { d: "An I2C slave holding SCL low to make the master wait until it is ready. Not all masters support it, which is a real compatibility trap.", l: "emb-buses" },
"CPHA": { d: "SPI clock phase: which clock edge the data is sampled on. Getting it wrong shifts every bit one position, so 0x41 reads back as 0x82.", l: "emb-buses", aka: ["CPOL", "SPI mode"] },
"full duplex": { d: "Both directions carry data simultaneously, as SPI does on MOSI and MISO. It is why MOSI going quiet during a read is correct rather than a fault.", l: "emb-buses" },
"baud rate": { d: "Symbols per second on a UART. Derived by dividing a clock by an integer, so rounding error grows as the divider shrinks, which is why high rates fail first.", l: "emb-buses", aka: ["baud", "baud divider"] },
"framing": { d: "How a receiver knows where one message ends and the next begins: fixed length, a length prefix, or a delimiter with escaping. Only the delimiter resynchronises by itself.", l: "emb-serial" },
"COBS": { d: "Consistent Overhead Byte Stuffing: an encoding that removes a chosen delimiter byte from the payload with a small, bounded and predictable overhead.", l: "emb-serial" },
"CRC": { d: "A checksum computed as polynomial division, chosen so common physical error patterns are guaranteed detectable. Detects accidental corruption only: an attacker can recompute it.", l: "emb-crc" },
"check value": { d: "The CRC of the ASCII string 123456789, published for every catalogued CRC. Running yours against it proves all six parameters match, and it needs no hardware.", l: "emb-crc" },
"polynomial": { d: "The fixed constant a CRC divides by, written as a bit pattern such as 0x1021. Naming it is not enough to specify a CRC: init, reflection, final XOR and coverage must also be agreed.", l: "emb-crc" },
"bit reflection": { d: "Whether a CRC processes bits least significant first, and whether the result is bit-reversed. CRC-32 reflects both; CRC-16/CCITT-FALSE reflects neither. One of the six parameters that must be agreed.", l: "emb-crc", aka: ["reflected"] },
"checksum": { d: "Any short value computed over data to detect corruption. A plain additive sum is blind to reordering, since addition is commutative, which is why a CRC is usually preferred.", l: "emb-crc" },
"HMAC": { d: "A keyed hash. Unlike a CRC it cannot be recomputed without the secret, so it detects deliberate tampering as well as accidental corruption.", l: "emb-serial" },

// ---- drivers, testing and process -----------------------------------------
"HAL": { d: "Hardware Abstraction Layer: the vendor's C API over the peripheral registers, such as <code>HAL_I2C_Master_Transmit</code>. Convenient, but calling it from a device driver welds that driver to one vendor's silicon and kills off-target testing.", l: "emb-drivers", aka: ["vendor HAL", "vendor SDK"] },
"GPIO": { d: "General Purpose Input/Output: a pin your firmware controls directly. Toggling a spare one is the cheapest accurate way to time a section of code on a scope.", l: "emb-buses" },
"FPU": { d: "Floating Point Unit. Where one exists, floats are usually the simpler choice. Using it inside an interrupt handler may require saving and restoring its context, which adds cycles to every such interrupt.", l: "emb-fixedpoint" },

// ---- bus signal names ------------------------------------------------------
"SDA": { d: "Serial Data: the I2C data line. Open-drain, so devices only pull it low and a pull-up returns it high. It may only change while SCL is low, except for START and STOP.", l: "emb-buses" },
"SCL": { d: "Serial Clock: the I2C clock line, driven by the master. A slave may hold it low to stall the master, which is clock stretching.", l: "emb-buses" },
"MOSI": { d: "Master Out, Slave In: the SPI line the master drives. It goes idle during a read phase because the master has nothing left to send, which is correct behaviour rather than a fault.", l: "emb-buses" },
"MISO": { d: "Master In, Slave Out: the SPI line the addressed slave drives. Reading all 0xFF means nothing is driving it at all.", l: "emb-buses" },
"chip select": { d: "The SPI line that picks which device is being addressed. It must be asserted before the first clock edge and held for the whole transfer, and it is why SPI needs no address byte.", l: "emb-buses", aka: ["chip selects"] },
"SPI": { d: "A four-wire full duplex bus: clock, MOSI, MISO and a chip select per device. No addressing and no acknowledgement, so the bus never tells you a device is absent.", l: "emb-buses" },
"UART": { d: "An asynchronous serial link with no clock line. Both ends agree a bit rate and the receiver samples the middle of each bit, which is why total timing error must stay within about 2 to 3 per cent.", l: "emb-buses" },
"STOP condition": { d: "On I2C, SDA rising while SCL is high. It ends the transaction and releases the bus. A slave holding SDA low makes it impossible to generate, which is why a stuck bus needs clocking out.", l: "emb-buses" },
"RC time constant": { d: "Resistance times capacitance, setting how fast a passively pulled line rises. It is why I2C rise time depends on the pull-up value and the bus capacitance, and why released edges curve while driven edges are sharp.", l: "emb-buses", aka: ["RC"] },

"injected transport": { d: "Passing a driver a small struct of function pointers (read, write, delay) plus an opaque context, instead of letting it call the vendor HAL. This is what makes it testable on a host.", l: "emb-drivers", aka: ["dependency injection", "transport struct"] },
"ctx": { d: "Short for context. A <code>void *</code> the caller supplies and the driver hands back untouched on every call, never looking inside it. It is how a callback finds its own data, and without it an adapter needs a global and can only ever serve one device.", l: "emb-drivers", aka: ["context pointer", "user pointer", "user data"] },
"handle": { d: "A token standing for something a library owns. You get it from a create function, pass it back to every other call, and return it at destroy. You never look inside: like a cloakroom ticket, it is not the coat.", l: "emb-drivers", aka: ["handles"] },
"config struct": { d: "A struct you fill in and pass to a create function. Beats a long parameter list because fields are named at the call site, unset fields default to zero, and adding one later does not break existing callers.", l: "emb-drivers", aka: ["configuration struct"] },
"unit test": { d: "A test of one unit of logic in isolation, with its dependencies replaced by doubles, run on the host rather than on target. Fast enough to run on every commit, and it still works when the client's hardware has gone back.", l: "emb-testing", aka: ["unit tests", "unit testing", "host test", "host tests"] },
"bench bring-up": { d: "Answering 'is this particular board good', by hand, once: rails at their test points, current draw sane, clock running, chip IDs reading back. Write the known-good values down, because they are what lets you diagnose the next board by comparison.", l: "emb-hil", aka: ["bring-up", "board bring-up"] },
"test double": { d: "Any stand-in for a real dependency in a test. The four kinds are stub (fixed answers), spy (records calls), fake (simplified working version) and mock (records and asserts expectations).", l: "emb-testing", aka: ["test doubles", "doubles"] },
"HIL": { d: "Hardware In the Loop: a PC driving the target plus programmable instruments over their comms ports, so scenarios run repeatably and produce a report.", l: "emb-hil", aka: ["hardware in the loop"] },
"TDD": { d: "Test Driven Development: write a failing test, make it pass, refactor. The red step matters because a test that has never failed may assert nothing at all.", l: "emb-tdd-loop" },
"FIRST": { d: "The properties of a good unit test: Fast, Isolated, Repeatable, Self-verifying, Timely. Isolated is the one most often broken, by state leaking between tests.", l: "emb-tdd-loop", cs: 1 },
"test list": { d: "The cases written down before any test is written. It surfaces error paths while they are still cheap, and turns 'what next' into a queue rather than a decision made mid-problem.", l: "emb-tdd-loop" },
"stub": { d: "A test double that returns canned answers and remembers nothing. Enough to keep the code under test running so you can assert on its result.", l: "emb-tdd-doubles", aka: ["stubs", "stubbing"] },
"spy": { d: "A test double that records calls, arguments and order, so the test can assert on the interaction afterwards. What you need to check that init wrote a register after the reset, not before.", l: "emb-tdd-doubles", aka: ["spies"] },
"mock": { d: "A test double programmed with expectations up front, failing during execution when they are violated. What CMock generates. Binds tightly to the call sequence, so it can be brittle under refactoring.", l: "emb-tdd-doubles", aka: ["mocks", "mocking"] },
"seam": { d: "A place where behaviour can be changed without editing at that place. C has three: link, preprocessing and object. The link seam is the one that lets you test legacy code without touching it.", l: "emb-tdd-legacy", aka: ["seams", "link seam", "object seam"] },
"characterisation test": { d: "A test recording what code currently does, bugs included, rather than what it should do. Written by guessing an assertion, letting it fail, and putting the real answer in.", l: "emb-tdd-legacy", aka: ["characterisation tests", "characterization test"] },
"legacy code": { d: "Feathers' definition: code without tests. Deliberately blunt, because it makes the problem about the missing safety net rather than about age or style.", l: "emb-tdd-legacy" },
"dual targeting": { d: "The same source builds and runs on the host for development and on the target for the real thing. What makes host tooling like sanitizers and coverage available to firmware logic.", l: "emb-tdd-dualtarget", aka: ["dual target"] },
"UBSan": { d: "UndefinedBehaviorSanitizer. Instruments a host build to catch signed overflow, out-of-range shifts, misaligned access and null dereference at run time, with a file and line. No on-target equivalent.", l: "emb-tdd-dualtarget", aka: ["UndefinedBehaviorSanitizer", "sanitizer", "sanitizers"] },
"AddressSanitizer": { d: "Detects buffer overflows, use-after-free and related memory errors in a host build. Together with UBSan it is the strongest argument for building firmware logic off-target.", l: "emb-tdd-dualtarget", aka: ["ASan"] },
"Unity": { d: "A small C unit test framework: assertion macros plus a runner. Its runner generator matters because C has no reflection, so a hand-written runner silently omits tests you forgot to register.", l: "emb-tdd-unity" },
"CMock": { d: "Generates mock implementations from a C header, substituted at link time. Excellent for an API you cannot modify; the resulting tests bind to the exact call sequence.", l: "emb-tdd-unity" },
"Ceedling": { d: "The build glue tying Unity, CMock and rake together by convention, so each test file is compiled against its module with mocks generated automatically.", l: "emb-tdd-unity" },
"CppUTest": { d: "The framework Grenning's book mostly uses. Written in C++ but tests C, and notable for built-in memory leak detection that fails a test and names the file and line.", l: "emb-tdd-unity" },
"humble object": { d: "Making the untestable layer as thin and decision-free as possible, so all the logic lives somewhere testable. An ISR that reads a register and calls a tested function is the canonical firmware example.", l: "emb-tdd-design" },
"dependency inversion": { d: "The high-level policy should not depend on the low-level detail; both depend on an abstraction. In C that is a struct of function pointers the driver declares and the adapter satisfies.", l: "emb-tdd-design" },
"mutation testing": { d: "Deliberately changing the code to see whether a test fails. A surviving mutant is a hole in the assertions, which is exactly what coverage cannot detect.", l: "emb-tdd-coverage", aka: ["mutant", "surviving mutant"] },
"branch coverage": { d: "Whether every decision went both ways. Meaningfully stronger than statement coverage, which only asks whether a line ran.", l: "emb-tdd-coverage", aka: ["statement coverage", "code coverage", "coverage"] },
"MC/DC": { d: "Modified Condition/Decision Coverage: each sub-condition in a compound expression must be shown to independently change the outcome. Required for DO-178C Level A avionics.", l: "emb-tdd-coverage" },
"flaky test": { d: "A test that sometimes passes. It destroys trust in the whole suite, because people start rerunning failures instead of reading them. Fix it or delete it, never retry it.", l: "emb-tdd-coverage", aka: ["flaky tests", "flakiness"] },
"gcov": { d: "The GCC coverage tool. Build with --coverage at -O0, run the tests, and it reports which lines executed. Measure at -O0 because optimisation makes coverage hard to attribute to source lines.", l: "emb-tdd-coverage", aka: ["lcov"] },
"static analysis": { d: "Tooling that reasons across function boundaries and along execution paths, finding things a compiler misses: leaks on error paths, null dereferences across calls.", l: "emb-defensive", aka: ["static analyser", "static analyzer"] },
"MISRA": { d: "A coding standard for critical embedded C. Its real value is the deviation process, which turns a rule violation into an argued decision on the record.", l: "emb-defensive" },
"deviation": { d: "A recorded, justified departure from a coding standard rule. What separates a considered exception from an accident nobody noticed.", l: "emb-defensive", aka: ["deviations", "deviation process"] },
"traceability": { d: "The link from a test result back to the requirement it verifies. It is the evidence regulated work needs, and it exposes requirements no test covers.", l: "emb-hil" },

// ---- numeric, state, timing -----------------------------------------------
"fixed point": { d: "Representing fractions using integers with an implied binary point. Q16.16 means 16 integer bits and 16 fractional bits, so the stored value is the real value times 65536.", l: "emb-fixedpoint", aka: ["fixed-point", "Q format", "Q16.16"] },
"saturation": { d: "Clamping a value at its limit instead of letting it wrap. Wrapping turns full forward into full reverse, which for an actuator is a safety issue.", l: "emb-fixedpoint", aka: ["saturate", "saturating"] },
"state machine": { d: "Explicit named states plus defined transitions, replacing a set of booleans whose illegal combinations nobody has enumerated.", l: "emb-fsm", aka: ["state machines", "FSM", "finite state machine"] },
"hierarchical state machine": { d: "A state machine where a parent state holds behaviour common to its children, so shared transitions are written once. Usually overkill below about a dozen states.", l: "emb-fsm", aka: ["HSM"] },
"rate monotonic": { d: "A fixed-priority scheduling policy where the shortest period gets the highest priority. Provably optimal among fixed-priority policies for independent periodic tasks.", l: "emb-realtime", aka: ["rate monotonic scheduling", "RMS"] },
"utilisation bound": { d: "The CPU load below which a set of independent periodic tasks is guaranteed schedulable under rate monotonic: about 69 per cent. Above it you must analyse rather than assume.", l: "emb-realtime", aka: ["utilization bound"] },
"hard real time": { d: "A missed deadline is a system failure. It is about consequence, not speed: a slow system with a guaranteed deadline is hard real time, a fast one without a guarantee is not.", l: "emb-realtime", aka: ["hard real-time", "soft real time", "soft real-time"] },

// ---- DMA, cache, power, storage -------------------------------------------
"DMA": { d: "Direct Memory Access: a controller that moves data without the CPU, so the core can sleep or do other work. It is a separate bus master, so masking interrupts does not stop it.", l: "emb-dma" },
"cache coherency": { d: "Keeping what the CPU sees in cache consistent with what is actually in memory. DMA writes to RAM directly, so the CPU may hold a stale cached line unless you invalidate it.", l: "emb-dma", aka: ["coherency", "cache coherence"] },
"cache line": { d: "The unit a cache loads and evicts, typically 32 or 64 bytes. Cache maintenance works on whole lines, which is why a DMA buffer sharing a line with other variables is dangerous.", l: "emb-dma", aka: ["cache lines"] },
"cache invalidate": { d: "Discarding cached lines so the CPU re-reads from actual memory. Needed <b>after</b> DMA has written a buffer. The opposite operation, cache clean, pushes your writes out before DMA reads them.", l: "emb-dma", aka: ["cache clean", "cache maintenance"] },
"write buffer": { d: "Hardware that holds stores briefly before they reach memory. It is why a barrier can be needed even when volatile has already forced the store to be emitted.", l: "emb-dma" },
"circular mode": { d: "A DMA mode where the controller wraps to the start of the buffer automatically, with half and full interrupts so you process one half while hardware fills the other.", l: "emb-dma" },
"duty cycle": { d: "The fraction of time something is active. On a battery device it dominates average current, because active current is typically a thousand times sleep current.", l: "emb-power" },
"PLL": { d: "Phase-Locked Loop: multiplies a reference clock up to the CPU frequency. If it fails to lock most parts run quietly from a fallback source, and every timing calculation is then wrong.", l: "emb-power" },
"RC oscillator": { d: "An on-chip clock source needing no crystal, typically accurate to one or two per cent and worse over temperature. That error alone can consume the whole UART tolerance budget.", l: "emb-power", aka: ["internal RC"] },
"deep sleep": { d: "A low-power mode that powers down most of the chip. RAM outside a small retention region is lost, so waking resembles a reset, and only an armed source can wake it at all.", l: "emb-power" },
"retention": { d: "The small region of RAM that stays powered through deep sleep. Anything that must survive goes here or in non-volatile storage.", l: "emb-power", aka: ["retention RAM", "retention region"] },
"endurance": { d: "How many erase cycles a flash sector tolerates, commonly 10,000 to 100,000. It is per sector, so a scheme that hammers one sector kills the product while the rest is untouched.", l: "emb-flash" },
"wear levelling": { d: "Spreading erases across sectors so no single one wears out first. Without it, one hot record concentrates every erase on one sector.", l: "emb-flash", aka: ["wear leveling"] },
"log-structured": { d: "A storage scheme that only ever appends records, erasing a sector when it fills. Multiplies flash life by the records per sector, and leaves the previous record valid until compaction.", l: "emb-flash" },
"A/B slots": { d: "Two firmware partitions, so a new image is written to the inactive one and verified before switching. There is no window in which a power failure leaves the device unbootable.", l: "emb-bootloader", aka: ["A/B partitions", "dual slot"] },
"anti-rollback": { d: "Refusing to boot an image older than a recorded version counter, to stop an attacker reinstating a vulnerable release. Conflicts with the reliability wish to revert a broken update.", l: "emb-bootloader" },
"secure boot": { d: "Verifying a cryptographic signature on the firmware before running it. A CRC proves integrity only; a signature proves origin, which is what stops an attacker's image running.", l: "emb-sec-boot" },

// ---- analogue and signals, firmware side ----------------------------------
"acquisition time": { d: "How long the ADC connects its sampling capacitor to your pin before converting. It charges through <b>your</b> source resistance, so the requirement is a property of your circuit: roughly nine time constants for 12-bit settling.", l: "emb-adc-fw", aka: ["sampling time"] },
"ratiometric": { d: "The sensor's excitation and the ADC's reference are the same voltage, so it cancels and the reading depends only on a ratio. Supply variation stops mattering, which is why a precision reference can make such a measurement worse.", l: "emb-units" },
"LSB": { d: "Least Significant Bit: the smallest step an ADC or DAC can represent, equal to the reference divided by the number of levels. Oversampling needs about one LSB of noise present to work at all.", l: "emb-adc-fw" },
"oversampling": { d: "Taking 4^n samples, summing and shifting right by n to gain n bits of resolution. Requires at least about one LSB of uncorrelated noise, so a perfectly quiet input gains nothing.", l: "emb-averaging", aka: ["oversample", "dither"] },
"decimation": { d: "Sampling faster than needed and reducing the rate afterwards, usually with filtering. One legitimate answer to aliasing when a hardware filter is not an option.", l: "emb-averaging", aka: ["decimate"] },
"aliasing": { d: "A frequency above half the sample rate folding down and becoming indistinguishable from a real signal at the folded frequency. Cannot be undone in firmware, so the anti-alias filter must be in hardware before the ADC.", l: "emb-sampling", aka: ["alias", "anti-alias filter", "aliased"] },
"input capture": { d: "The timer latching its count in hardware at a signal edge. Makes an event timestamp exact regardless of when your handler runs, unlike reading the counter in software.", l: "emb-sampling" },
"slew rate": { d: "How fast a signal is changing. It is what converts sampling jitter into amplitude error, which is why the same jitter is harmless on a slow signal and severe on a fast one.", l: "emb-sampling" },
"EMA": { d: "Exponential moving average, a one-pole IIR filter: <code>y += (x - y) &gt;&gt; K</code>. One state variable and one tuning knob, but the naive integer form stops tracking once the error falls below 2^K.", l: "emb-filter-fw", aka: ["exponential moving average", "one-pole"] },
"moving average": { d: "N samples summed and divided. Exactly linear phase, and it has nulls at multiples of the sample rate over N, so choosing N as one mains period removes hum for free.", l: "emb-filter-fw", aka: ["boxcar"] },
"median filter": { d: "The only common firmware filter that removes an impulsive spike rather than smearing it across an impulse response. Use it before calibration so a wild value cannot be scaled into something enormous.", l: "emb-filter-fw" },
"group delay": { d: "How much a filter delays the signal. In a control loop it is spent phase margin, which is why smoothing feedback to make it look nicer is a classic way to destabilise a loop.", l: "emb-filter-fw" },
"preload": { d: "A timer's shadow register: a write to the compare value is buffered and applied at the next update event, so a duty change cannot produce one cycle of the wrong width. Often disabled by default.", l: "emb-pwm", aka: ["shadow register"] },
"dead time": { d: "A hardware-inserted gap where both transistors of a half bridge are off, preventing shoot-through. Must be generated by the timer, never in software, because one badly placed interrupt destroys the bridge.", l: "emb-pwm" },
"shoot-through": { d: "Both transistors in a half bridge conducting at once, shorting the supply through them. What dead time exists to prevent.", l: "emb-pwm" },
"centre-aligned": { d: "PWM counting up then down, so the pulse is symmetric about the period midpoint. Costs half the resolution, buys lower harmonic content and an update event at a quiet moment that makes a good ADC trigger.", l: "emb-pwm", aka: ["center-aligned", "edge-aligned"] },
"duty cycle resolution": { d: "The number of distinct PWM levels, equal to the timer clock divided by the PWM frequency. Switching frequency, magnetic size, audible noise and control resolution are all the same knob.", l: "emb-pwm" },
"two-point calibration": { d: "Measuring two known values near each end of the range to solve for both offset and gain. One point solves only for offset, assuming nominal gain; more points address linearity, which is a different model.", l: "emb-calib", aka: ["one-point calibration"] },
"offset and gain": { d: "The two coefficients of <code>corrected = (raw - offset) * gain</code>. Offset removes the constant error, gain the proportional one. Both are per unit, so they live in non-volatile storage rather than in the source.", l: "emb-calib" },

// ---- security -------------------------------------------------------------
"threat model": { d: "A written record of what is worth taking, who would take it, what it costs them, and what you decided to do. Its value is recording what you deliberately did <b>not</b> defend, and what would make you revisit.", l: "emb-sec-threat", aka: ["threat modelling", "threat modeling"] },
"STRIDE": { d: "Six categories to walk each interface through: Spoofing, Tampering, Repudiation, Information disclosure, Denial of service, Elevation of privilege. Useful mainly for surfacing the ones you would not have thought of.", l: "emb-sec-threat" },
"attack surface": { d: "Every input a device accepts. The forgotten ones are the interesting ones: USB descriptors parsed before authentication, BLE provisioning, a debug console, and above all the update mechanism.", l: "emb-sec-threat" },
"root of trust": { d: "The one thing in a chain of trust that cannot be replaced, typically mask ROM in silicon plus key material in fuses. Running first is not enough: if it can be replaced, the attacker replaces the thing doing the checking.", l: "emb-sec-boot" },
"chain of trust": { d: "Each boot stage verifies the next before handing over. Break any link and everything above it is untrusted, which is why a replaceable bootloader makes the application's signature check meaningless.", l: "emb-sec-boot" },
"signature": { d: "An asymmetric authenticity check. The device holds only the public key, so extracting it gains an attacker nothing. This is why secure boot uses one rather than a MAC, which would put a fleet-wide signing key on every device.", l: "emb-sec-boot", aka: ["Ed25519", "ECDSA", "digital signature"] },
"OTP": { d: "One-time-programmable memory, or fuses. Writable once and, on good parts, readable by the CPU but not through the debug interface. Where a key or a key hash belongs.", l: "emb-sec-keys", aka: ["eFuse", "eFuses", "fuses"] },
"secure element": { d: "A separate chip that generates a key internally and never releases it: you send data in and get a signature out. Even full compromise of your MCU does not yield the key.", l: "emb-sec-keys", aka: ["ATECC608", "SE050"] },
"per-device key": { d: "A distinct key in each unit, so an extraction compromises one device rather than the fleet. The single most consequential decision in key storage, and it matters more than the storage mechanism.", l: "emb-sec-keys", aka: ["per-device keys", "shared key"] },
"KDF": { d: "Key Derivation Function, such as HKDF. Produces independent purpose-specific keys from one root, so compromising the storage key does not hand over the link key, and the root is rarely touched.", l: "emb-sec-keys", aka: ["HKDF", "key derivation", "key hierarchy"] },
"provisioning": { d: "Getting keys and identities onto devices at manufacture. Often the weakest part of a sound design: a CA private key on a factory laptop is a bigger risk than anything on the device.", l: "emb-sec-keys" },
"AEAD": { d: "Authenticated Encryption with Associated Data: AES-GCM, AES-CCM, ChaCha20-Poly1305. Does confidentiality and authenticity in one construction, so there is no ordering to get wrong and no coverage gap.", l: "emb-sec-crypto", aka: ["AES-GCM", "ChaCha20-Poly1305", "AES-CCM"] },
"nonce": { d: "A number used once. Reusing one with the same key in GCM is catastrophic rather than merely weakening: it leaks the XOR of the plaintexts and permits tag forgery. On embedded the usual cause is a counter that resets on reboot.", l: "emb-sec-crypto", aka: ["nonce reuse", "IV"] },
"ECB": { d: "The block cipher mode that encrypts each block independently, so identical plaintext blocks give identical ciphertext and the structure shows through. It is in every textbook and is essentially never the right answer.", l: "emb-sec-crypto" },
"constant time": { d: "Code whose execution time does not depend on secret data. Comparing a MAC with <code>memcmp</code> returns early, leaking how many leading bytes matched, which is enough to forge a tag byte by byte.", l: "emb-sec-crypto", aka: ["constant-time"] },
"TRNG": { d: "A hardware true random number generator. Everything cryptographic depends on unpredictable numbers, and seeding a PRNG from a serial number or boot time has left real fleets with only a few thousand possible keys.", l: "emb-sec-crypto" },
"readout protection": { d: "Blocking debug access to flash. On ST, level 1 allows a revert that mass-erases the flash, so contents are destroyed rather than exposed; level 2 is permanent and removes any ability to debug a field return.", l: "emb-sec-debug", aka: ["RDP", "debug lockout"] },
"glitching": { d: "Briefly disturbing the supply voltage or clock so the core skips or misexecutes an instruction, typically aimed at the branch after a signature check. Cheap equipment, well documented, and countermeasures raise the cost rather than removing the attack.", l: "emb-sec-debug", aka: ["fault injection", "voltage glitching"] },
"side channel": { d: "Recovering a key from measurements such as power consumption or timing rather than from memory. The reason to use a library or hardware engine with documented countermeasures rather than your own clean-looking implementation.", l: "emb-sec-debug", aka: ["side-channel", "power analysis"] },
"replay": { d: "Resending a genuinely valid captured message. Encryption and authentication do nothing about it, because the message really was authentic. Defences are a reboot-surviving counter, a timestamp, or challenge and response.", l: "emb-sec-comms", aka: ["replay attack", "freshness"] },
"TLS-PSK": { d: "TLS with a pre-shared key, removing certificates, chain validation and most of the handshake cost while keeping the security properties. Trades away the ability to rotate trust without touching the device.", l: "emb-sec-comms", aka: ["pre-shared key"] },
"Just Works": { d: "The BLE pairing mode with no man-in-the-middle protection, so an attacker present during pairing can insert themselves. It is the default because it needs no display or keypad, which makes pairing security a hardware decision.", l: "emb-sec-comms", aka: ["Passkey Entry", "Numeric Comparison", "LE Secure Connections"] },
"certificate validation": { d: "Checking a presented certificate against a trusted root and checking the hostname. Skipping it leaves encryption against a passive listener and nothing against an active one, and it looks identical in testing.", l: "emb-sec-comms" },
"SBOM": { d: "Software Bill of Materials: every component in the image and its exact version. Without one, 'are we affected by this advisory?' has no answer, which is what made Ripple20 so hard to respond to.", l: "emb-sec-practice", aka: ["software bill of materials"] },
"PSTI": { d: "The UK Product Security and Telecommunications Infrastructure Act. Three obligations on consumer connectable products: no universal default passwords, a published means to report security issues, and a published minimum update period.", l: "emb-sec-practice", aka: ["Cyber Resilience Act", "CRA"] },
"vulnerability disclosure": { d: "A published contact point and stated response process. Without one, a researcher who finds a flaw can only give up or publish. It is a page and an email address, and a UK legal requirement for consumer connectable products.", l: "emb-sec-practice", aka: ["disclosure policy"] },

// ---- connectivity ---------------------------------------------------------
"enumeration": { d: "The sequence of control transfers a USB host performs to discover a device: descriptors, address assignment, then configuration. Every step has a timeout, so a slow or wrong answer means the device simply does not appear.", l: "emb-usb", aka: ["enumerate", "enumerates"] },
"descriptor": { d: "The data structures a USB device returns describing itself. wTotalLength covering the whole concatenated blob, bMaxPower in 2 mA units and every bLength are all silent when wrong.", l: "emb-usb", aka: ["descriptors"] },
"endpoint": { d: "A USB data channel with a direction and a type: control, bulk (delivered but unbounded latency), interrupt (bounded latency, small packets) or isochronous (guaranteed bandwidth, no retries).", l: "emb-usb", aka: ["endpoints"] },
"zero-length packet": { d: "Sent to terminate a USB transfer whose length is an exact multiple of the maximum packet size, since a transfer normally ends on a short packet. Omitting it makes exactly those sizes hang.", l: "emb-usb", aka: ["ZLP"] },
"GATT": { d: "The BLE data model once connected: services containing characteristics, each with a UUID, a value, and properties such as read, write, notify and indicate.", l: "emb-ble", aka: ["characteristic", "characteristics"] },
"GAP": { d: "The BLE layer covering discovery and connection: who advertises, who scans, who connects. Your device is usually the peripheral.", l: "emb-ble", aka: ["advertising", "peripheral role"] },
"ATT MTU": { d: "The BLE attribute protocol packet size. Defaults to 23 bytes, leaving 20 of payload; negotiating to 247 gives 244. Not doing so is the most common reason a BLE link is slow.", l: "emb-ble", aka: ["MTU"] },
"notify": { d: "An unacknowledged BLE push from peripheral to central. Several can go out per connection event, which is what makes it usable for streaming.", l: "emb-ble", aka: ["notification", "notifications"] },
"indicate": { d: "An acknowledged BLE push. Only one can be outstanding at a time, so each costs a round trip, making it roughly an order of magnitude slower than notify.", l: "emb-ble", aka: ["indication"] },
"connection interval": { d: "How often a BLE connection has an exchange opportunity: 7.5 ms minimum, 4 s maximum. The first number in any BLE throughput or latency calculation.", l: "emb-ble" },
"slave latency": { d: "Permission for a BLE peripheral to skip connection events when it has nothing to send, giving low latency when active and low power when idle. The supervision timeout must exceed interval times latency plus one.", l: "emb-ble", aka: ["supervision timeout"] },
"DLE": { d: "Data Length Extension: raises the BLE link-layer payload from 27 to 251 bytes. Needed alongside a larger ATT MTU, or a large ATT packet is just fragmented across several radio packets.", l: "emb-ble", aka: ["data length extension"] },
"bus-off": { d: "A CAN node disconnecting itself once its transmit error counter exceeds 255. Designed behaviour, so a failing transceiver cannot destroy the bus. Firmware must recover from it and count it.", l: "emb-can", aka: ["error-passive", "error active"] },
"arbitration": { d: "How CAN resolves simultaneous transmission: a dominant 0 overrides a recessive 1, so the lowest identifier wins bit by bit and the loser stops without corrupting anything.", l: "emb-can", aka: ["non-destructive arbitration"] },
"sample point": { d: "The fraction through a CAN bit at which the controller samples, typically 75 to 87.5 per cent. All nodes must agree closely enough, and propagation delay eats the margin as the cable lengthens.", l: "emb-can" },
"pbuf": { d: "lwIP's packet buffer, allocated from a pool fixed at build time. When the pool empties the stack drops packets silently, which TCP turns into a throughput collapse rather than an error.", l: "emb-net", aka: ["pbufs"] },
"lwIP": { d: "The common small TCP/IP stack. Its raw callback API has the smallest footprint; the BSD socket API is the most convenient and needs a thread per blocking connection.", l: "emb-net" },
"Nagle": { d: "A TCP optimisation holding a small send until previous data is acknowledged. Combined with delayed ACK on a request-response link it produces a reliable 200 ms stall per exchange.", l: "emb-net", aka: ["delayed ACK", "TCP_NODELAY"] },
"duplex mismatch": { d: "One end half duplex and the other full. The link works at low rates and collapses under load, because collisions only start mattering when both directions are busy.", l: "emb-net" },
"idempotent": { d: "Safe to repeat. Reading a temperature is; incrementing a counter is not. Because links lose messages and senders retry, a protocol has to say what a duplicate command means.", l: "emb-protodesign", aka: ["idempotency", "at-least-once", "at-most-once"] },
"TLV": { d: "Type-length-value encoding. Costs a few bytes per field and lets a receiver skip fields it does not recognise, turning a future field addition from a breaking change into an upgrade path.", l: "emb-protodesign", aka: ["type-length-value"] },
"flow control": { d: "A mechanism letting the receiver say slow down. Without it a streaming protocol loses data silently when the consumer cannot keep up, which is the worst property a data path can have.", l: "emb-protodesign" },

// ---- general electronics and systems --------------------------------------
"ADC": { d: "Analogue to Digital Converter. Measures its input as a fraction of its reference, so the reference is as much part of your accuracy as the converter is.", l: "emb-adc-fw", aka: ["DAC"] },
"RTOS": { d: "Real-Time Operating System: a scheduler plus synchronisation primitives. Justified by tasks with different rates, blocking work, or different priorities, not by tidiness.", l: "emb-rtos" },
"VDD": { d: "The positive supply rail. Using it as the ADC reference is right when the sensor is also powered from it (ratiometric) and wrong when the sensor has its own reference.", l: "emb-units", aka: ["VCC"] },
"SAR": { d: "Successive Approximation Register: the common ADC architecture that makes one bit decision per clock. Rushing its clock makes those decisions marginal, which looks like noise rather than failure.", l: "el-adc" },
"ENOB": { d: "Effective Number Of Bits: the resolution a converter actually delivers once its noise and distortion are accounted for, which is always less than its nominal bit count.", l: "el-adc", aka: ["SINAD"] },
"LDO": { d: "Low Drop-Out regulator: a linear regulator that works with a small input-to-output difference. Quiet, simple, and it dissipates the voltage difference times the current as heat.", l: "el-power" },
"ESR": { d: "Equivalent Series Resistance: the unwanted resistance in series with a capacitor. It limits how well a decoupling capacitor can supply a fast current transient.", l: "el-power" },
"PSRR": { d: "Power Supply Rejection Ratio: how well a circuit ignores noise on its supply. It falls with frequency, which is why decoupling matters more than a good regulator alone.", l: "el-power" },
"TVS": { d: "Transient Voltage Suppressor: a diode that clamps a voltage spike to protect what is downstream. The first line of defence on any externally exposed pin.", l: "el-protection" },
"FET": { d: "Field Effect Transistor. As a switch, what matters is on-resistance, gate charge and how fast the driver can move that charge, because switching losses live in the transition.", l: "el-mosfets", aka: ["MOSFET", "MOSFETs"] },
"DC": { d: "Direct current, or a signal's zero-frequency component. A DC offset is systematic, so averaging never removes it and only calibration will.", l: "emb-calib" },
"RF": { d: "Radio Frequency. At RF, wires become transmission lines and layout stops being a convenience and becomes part of the circuit.", l: "el-emc" },

// ---- DSP and maths --------------------------------------------------------
"SNR": { d: "Signal to Noise Ratio, usually in dB. Averaging N independent samples improves it by the square root of N, which is 3 dB per doubling.", l: "dsp-noise" },
"FIR": { d: "Finite Impulse Response filter: output depends only on a window of inputs, so it is unconditionally stable and can have exactly linear phase. The cost is more taps for the same selectivity.", l: "dsp-fir-design" },
"IIR": { d: "Infinite Impulse Response filter: output depends on previous outputs, so it is far cheaper than an FIR for the same selectivity, at the cost of nonlinear phase and possible instability.", l: "dsp-iir-design", aka: ["biquad"] },
"FFT": { d: "Fast Fourier Transform: an O(N log N) algorithm for the DFT. Its bins smear if your sampling had jitter, which is why sample timing matters upstream of any spectral work.", l: "dsp-spectral", aka: ["DFT"] },
"CFAR": { d: "Constant False Alarm Rate: a detector whose threshold adapts to the local noise, so the false alarm rate stays fixed as conditions change.", l: "dsp-detection" },
"LMS": { d: "Least Mean Squares: the simplest adaptive filter update, adjusting coefficients along the instantaneous gradient. Cheap, and its convergence depends on a step size you have to choose.", l: "dsp-adaptive" },
"ULP": { d: "Unit in the Last Place: the gap between adjacent representable floating point numbers. The natural unit for talking about rounding error, rather than a fixed epsilon.", l: "cm-float" },
"BFS": { d: "Breadth First Search: explores a graph level by level, so on an unweighted graph the first time it reaches a node is by a shortest path.", l: "cm-graphs", aka: ["DFS"] },
"MAP": { d: "Maximum A Posteriori: the most probable parameter value given the data and a prior. Maximum likelihood is the special case with a flat prior.", l: "cm-bayes", cs: 1 },

// ---- control --------------------------------------------------------------
"PID": { d: "Proportional, Integral, Derivative control. The integral term removes steady-state error and is also what needs anti-windup; the derivative term is what amplifies measurement noise.", l: "ct-robust" },
"LQR": { d: "Linear Quadratic Regulator: an optimal state-feedback gain found by minimising a weighted sum of state error and control effort. The design work is choosing the weights.", l: "ct-lqr" },
"MPC": { d: "Model Predictive Control: solve a constrained optimisation over a finite horizon each step, apply the first move, repeat. Handles constraints directly, at the cost of solving a problem in real time.", l: "ct-lqr" },
"EKF": { d: "Extended Kalman Filter: a Kalman filter linearised about the current estimate each step. Works well when the nonlinearity is mild and diverges when it is not.", l: "ct-fusion", aka: ["Kalman filter", "UKF"] },

// ---- robotics -------------------------------------------------------------
"ROS": { d: "Robot Operating System: not an OS but a middleware of nodes, topics and messages. ROS 2 replaces the central master with DDS discovery and adds quality-of-service settings.", l: "rob-ros", aka: ["ROS 2"] },
"IMU": { d: "Inertial Measurement Unit: accelerometers plus gyroscopes, sometimes a magnetometer. Gyros drift and accelerometers are noisy but bounded, which is exactly why the two are fused.", l: "rob-estimation" },
"DOF": { d: "Degrees Of Freedom: the number of independent motions a mechanism has. Six is the minimum to reach an arbitrary position and orientation in space.", l: "rob-kinematics" },
"IK": { d: "Inverse Kinematics: solving for joint angles that achieve a desired end-effector pose. Generally has multiple solutions, or none, unlike forward kinematics.", l: "rob-kinematics", aka: ["forward kinematics"] },
"RRT": { d: "Rapidly-exploring Random Tree: a sampling-based motion planner that grows a tree toward random points. Finds a path in high-dimensional spaces where grid search cannot.", l: "rob-planning" },
"CAN": { d: "Controller Area Network: a differential two-wire bus with priority arbitration by identifier, so the highest priority message wins without any node backing off. Standard in vehicles and increasingly in robots.", l: "emb-can" },
"BLDC": { d: "Brushless DC motor: commutated electronically rather than by brushes, which needs rotor position from Hall sensors, an encoder, or estimated back-EMF.", l: "rob-actuators" },
"VO": { d: "Visual Odometry: estimating motion by tracking features between camera frames. Drifts without loop closure, which is the difference between odometry and SLAM.", l: "rob-vo", aka: ["SLAM"] },

// ---- RTL and FPGA ---------------------------------------------------------
"RTL": { d: "Register Transfer Level: describing hardware as registers and the combinational logic between them, which is the abstraction synthesis actually understands.", l: "rtl-synth" },
"FPGA": { d: "Field Programmable Gate Array: a fabric of lookup tables, flip-flops, block RAM and DSP slices configured by a bitstream. Genuinely parallel, which is what distinguishes it from a fast CPU.", l: "rtl-fpga" },
"LUT": { d: "Look-Up Table: the FPGA's basic combinational element, a small truth table typically of four to six inputs. Logic utilisation is counted in these.", l: "rtl-fpga" },
"BRAM": { d: "Block RAM: dedicated memory blocks in the FPGA fabric, far more efficient than building storage out of flip-flops. Inferring them correctly depends on writing the access pattern the tool recognises.", l: "rtl-fpga" },
"CDC": { d: "Clock Domain Crossing: passing a signal between two unrelated clocks, where setup and hold cannot both be guaranteed and metastability becomes possible. Needs a synchroniser, or a FIFO for buses.", l: "rtl-cdc", aka: ["metastability"] },
"FIFO": { d: "First In First Out buffer. In hardware it is also the standard way to cross clock domains for multi-bit data, since a two-flop synchroniser only works for single bits.", l: "rtl-fifo" },
"AXI": { d: "ARM's on-chip bus family. AXI-Stream is the simple point-to-point version with a valid/ready handshake; full AXI adds addressing and independent read and write channels.", l: "rtl-axi", aka: ["AXI-Stream"] },
"DUT": { d: "Device Under Test: the module a testbench instantiates and drives. The name is worth knowing because it appears in every verification discussion.", l: "rtl-verif", aka: ["testbench"] },
"VHDL": { d: "The other main hardware description language. More verbose and more strongly typed than Verilog, and still dominant in aerospace and European industry.", l: "rtl-verilog", aka: ["Verilog", "SystemVerilog"] },

// ---- acoustics and NDT ----------------------------------------------------
"PRF": { d: "Pulse Repetition Frequency: how often a pulse-echo system fires. Too high and echoes from one pulse arrive during the next, which appears as wrap-around artefacts.", l: "ac-measurement" },
"NDT": { d: "Non-Destructive Testing: inspecting a part without damaging it. The commercial reason most industrial ultrasound exists.", l: "ac-measurement", aka: ["NDE"] },
"TFM": { d: "Total Focusing Method: capture every transmit-receive element pair, then focus computationally at every pixel afterwards. Better images than fixed delay laws, at a much higher data and compute cost.", l: "ac-imaging", aka: ["FMC"] },
"PZT": { d: "Lead zirconate titanate, the standard piezoelectric ceramic. High coupling and high acoustic impedance, which is why matching layers exist.", l: "ac-transducers", aka: ["PVDF"] },
"SPL": { d: "Sound Pressure Level in dB, referenced to 20 micropascals in air. The reference differs in water, which is why underwater and airborne figures cannot be compared directly.", l: "ac-safety", aka: ["MI"] },

// ---- software process -----------------------------------------------------
"CI": { d: "Continuous Integration: building and testing every commit on a clean machine. What proves the build does not depend on one engineer's local state.", l: "emb-build", aka: ["continuous integration"] },
"API": { d: "The interface a module presents to its callers. Designing it from the caller's side, by writing the imaginary call site first, is what stops you inventing error codes nobody checks.", l: "emb-errors" },
"RAII": { d: "Resource Acquisition Is Initialisation: tying a resource's lifetime to an object's scope so cleanup is automatic. C has no equivalent, which is why C uses goto-based unwinding instead.", l: "cpp-classes" },
"RAM": { d: "Volatile memory: writable and lost at power-off. That combination is why initialised globals cost both flash and RAM, and why deep sleep loses everything outside a retention region.", l: "emb-memory" },
"CPU": { d: "The processor core. Worth distinguishing from a DMA controller, which is a separate bus master and therefore not stopped by disabling interrupts.", l: "emb-cm-model" },
"ARM": { d: "The architecture family Cortex-M belongs to. Its calling convention, that R0 to R3 carry arguments and are caller-saved, is what makes a plain C function a legal interrupt handler.", l: "emb-cm-model" },

// ---- compiler and linker flags --------------------------------------------
"-O0": { d: "No optimisation. Code maps line-for-line to the source, so debugging is easy, but missing <code>volatile</code> and undefined behaviour are both invisible here. That is why a bug can appear only when you turn optimisation on.", l: "emb-build" },
"-O1": { d: "Light optimisation. Rarely used deliberately: -Og is the better development setting and -O2 or -Os the better release setting.", l: "emb-build" },
"-O2": { d: "Full optimisation for speed: inlining, loop transformations, reordering, and aggressive use of undefined behaviour to delete unreachable code. The usual release setting, and where volatile and UB bugs surface.", l: "emb-build" },
"-O3": { d: "-O2 plus more aggressive inlining and vectorisation. Often larger with little speed gain on a microcontroller, so it is rarely the right choice for embedded.", l: "emb-build" },
"-Os": { d: "Optimise for size: -O2 with the transformations that grow code (aggressive inlining, loop unrolling) disabled. Usually the right release setting on a flash-constrained part.", l: "emb-build" },
"-Og": { d: "Optimised but still debuggable. Keeps most optimisation while preserving a sensible line order and variable visibility. The right everyday development default.", l: "emb-build" },
"-Wall": { d: "Enables a large set of useful warnings. Despite the name it is not all of them: add -Wextra. Turning these on and fixing the fallout is usually the cheapest defect reduction available.", l: "emb-defensive" },
"-Wextra": { d: "A further set of warnings beyond -Wall, including unused parameters and some sign comparison issues.", l: "emb-defensive" },
"-Werror": { d: "Turns every warning into an error. This is what makes warnings stick: without it the count creeps up and nobody notices the new one among the old.", l: "emb-defensive" },
"-Wundef": { d: "Warns when an undefined identifier is used in an <code>#if</code>. Without it a typo in a config macro silently evaluates as 0 and disables a whole block.", l: "emb-defensive" },
"-Wconversion": { d: "Warns about implicit conversions that may change a value, such as assigning an <code>int</code> to a <code>uint8_t</code>. Noisy on existing code but valuable on new code.", l: "emb-defensive" },
"-Wshadow": { d: "Warns when a local variable hides one from an outer scope, which is a common source of 'I set it but it did not change'.", l: "emb-defensive" },
"-Wsizeof-pointer-memaccess": { d: "Catches <code>sizeof(buf)</code> on an array parameter passed to memcpy or memset, where it silently gives the pointer size. Part of -Wall.", l: "emb-pointers" },
"-Wmisleading-indentation": { d: "Warns when indentation suggests a statement is inside an <code>if</code> or loop when it is not. Catches many instances of the Apple goto fail shape, though not all.", l: "emb-defensive" },
"NDEBUG": { d: "The macro that compiles out <code>assert()</code>. It is why a runtime assert is absent in release builds, exactly where the check would matter, and why a static assert is preferable when the condition is constant.", l: "emb-errors" }

};
